import { EventAggregator, createDate, isNonEmptyArray } from "@/core/helpers";
import { OpeningHoursService } from "@/core/services";
import { ScheduleStore, ShowStore } from "@/core/stores";
import { useCallback, useEffect, useMemo, useState } from "react";
import {
  extendEvents,
  getDailyActivitiesContent,
  getDateSpan,
  getProductContent,
  getRideAndRestaurantContent,
  getRestaurantContent,
  getRideContentFromScheduleQueueTimes,
  transformParkOpeningHoursToCalendarData,
} from "../functions/daily-schedule-functions";
import { useFetchAllQueueTimes } from "@/core/hooks";
import dayjs from "dayjs";
import { ScheduleList } from "../daily-schedule";
import { useAttractionsSchedule } from "@/core/hooks/use-attractions-schedule";
import { useStaticConfigContext } from "@/core/contexts/static-config-context";

function useRemoteCall<T>(call: () => Promise<T>, shouldFetch: boolean) {
  const [data, setData] = useState<T>();
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    // This is to prevent the component from updating the state with data from a previous call if the user has shaky connection
    let isLatestCall = true;
    async function fetchData() {
      try {
        setIsLoading(true);
        if (shouldFetch) {
          const data = await call();
          if (isLatestCall) setData(data);
        }
      } catch (err) {
        EventAggregator.publish("trackException", {
          exception: err,
          customMessage: "DailySchedule event- and openingHoursPromise",
        });
      } finally {
        setIsLoading(false);
      }
    }
    fetchData();
    return () => {
      isLatestCall = false;
    };
  }, [call, shouldFetch]);

  return [data, isLoading] as const;
}

export function useEvents() {
  const getter = useCallback(async () => {
    const events = await ScheduleStore.getEventsForDates();
    return events && extendEvents(events);
  }, []);

  return useRemoteCall(getter, true);
}

export function useCalendarData(today?: Date) {
  const getter = useCallback(async () => {
    const openingHours = await OpeningHoursService.getAllDates();
    // Remove the first openinghours day if that day has passed. This it because the /openinghours/ endpoint may sometimes return yesterday as the first day.
    if (openingHours.length > 0 && dayjs(openingHours[0].opens).isBefore(today || createDate(), "day")) {
      openingHours.splice(0, 1);
    }

    return transformParkOpeningHoursToCalendarData(openingHours);
  }, [today]);

  return useRemoteCall(getter, true);
}

export function useRideAndRestaurantContent(selectedDate: Date, shouldFetch: boolean) {
  const { features } = useStaticConfigContext();
  const useScheduleEndpoint = features?.attractionScheduleEndpoint ?? false;

  // Old path: Contentful-based ride + restaurant content
  const oldGetter = useCallback(() => getRideAndRestaurantContent(selectedDate), [selectedDate]);
  const [oldContent, oldLoading] = useRemoteCall(oldGetter, shouldFetch && !useScheduleEndpoint);

  // New path: schedule endpoint for rides, Contentful for restaurants
  const restaurantGetter = useCallback(() => getRestaurantContent(selectedDate), [selectedDate]);
  const [restaurantContent, restaurantsLoading] = useRemoteCall(restaurantGetter, shouldFetch && useScheduleEndpoint);
  const { data: allQueueTimes, isLoading: queueTimesLoading } = useFetchAllQueueTimes({ enabled: useScheduleEndpoint });
  const { data: allSchedules, isLoading: schedulesLoading } = useAttractionsSchedule({}, useScheduleEndpoint);
  const newRideContent = useMemo(() => {
    if (!allQueueTimes || !allSchedules) return undefined;
    return getRideContentFromScheduleQueueTimes(allSchedules, allQueueTimes, selectedDate);
  }, [allSchedules, allQueueTimes, selectedDate]);

  if (useScheduleEndpoint) {
    const isLoading = restaurantsLoading || queueTimesLoading || schedulesLoading;
    return [{ rideContent: newRideContent, restaurantContent }, isLoading] as const;
  }
  return [oldContent, oldLoading] as const;
}

export function useDailyActivitiesContent(selectedDate: Date, shouldFetch: boolean) {
  const getter = useCallback(() => getDailyActivitiesContent(selectedDate), [selectedDate]);
  return useRemoteCall(getter, shouldFetch);
}

export function useProductContent(
  currentDisplayedMonth: Date,
  purchaseFlowIds: number[],
  purchaseFlows: ScheduleList,
  locale: string,
) {
  const getter = useCallback(() => {
    const datesOfCurrentMonth = getDateSpan(currentDisplayedMonth);
    return getProductContent(purchaseFlowIds, purchaseFlows, datesOfCurrentMonth, locale);
  }, [currentDisplayedMonth, purchaseFlowIds, purchaseFlows, locale]);

  return useRemoteCall(getter, !!currentDisplayedMonth && isNonEmptyArray(purchaseFlowIds));
}

export function usePromotionBanner(showConcertsInCalendar: boolean, today?: Date) {
  const getter = useCallback(async () => {
    const showsForPurchaseFlow = ShowStore.getShowsForPurchaseFlow();
    const showsForPurchaseFlowIds = showsForPurchaseFlow?.map((show) => show.contentful_id) ?? [];

    const shows = isNonEmptyArray(showsForPurchaseFlow)
      ? await ScheduleStore.getEventsForShowIds(showsForPurchaseFlowIds, today)
      : null;
    return shows;
  }, [today]);

  return useRemoteCall(getter, showConcertsInCalendar && !!today);
}
