import ServiceHelper from "./service-helper";
import { PurchaseFlowResponse } from "@/core/types/services/purchase-flow-service-types";

export type IPurchaseFlowService = {
  getPurchaseFlow(purchaseFlowId: number, locale: string): Promise<PurchaseFlowResponse>;
  getPurchaseFlows(
    purchaseFlowIds: Array<number>,
    dateFrom: string,
    dateTo: string,
    locale: string,
  ): Promise<Array<PurchaseFlowResponse>>;
};
export const PurchaseFlowService = {
  getPurchaseFlow(purchaseFlowId: number, locale: string) {
    return ServiceHelper.fetchGet(`/purchaseflows/${purchaseFlowId}?locale=${locale}`);
  },

  getPurchaseFlows(purchaseFlowIds: Array<number>, dateFrom: string, dateTo: string, locale: string) {
    const params = new URLSearchParams();

    for (const id of purchaseFlowIds) {
      params.append("purchaseFlowIds", id.toString());
    }

    params.append("dateFrom", dateFrom);
    params.append("dateTo", dateTo);
    params.append("locale", locale);

    return ServiceHelper.fetchGet(`/purchaseflows/?${params.toString()}`);
  },
} as IPurchaseFlowService;
