import { useMemo } from "react";
import { Matcher, dateMatchModifiers } from "react-day-picker";
import { matcherToArray } from "../calendar-helpers";
import dayjs from "dayjs";

export const useDisabledDatesClickable = (
  fromDate: Date,
  toDate: Date,
  disabledDates?: Matcher | Array<Matcher>,
): {
  fromDate: Date;
  toDate: Date;
  modifiers: Record<string, Matcher>;
} => {
  return useMemo(() => {
    return {
      fromDate: dayjs(fromDate).startOf("month").toDate(),
      toDate: dayjs(toDate).endOf("month").toDate(),
      modifiers: {
        clickableDisabled: (d: Date) =>
          dateMatchModifiers(d, [{ before: fromDate, after: toDate }, ...matcherToArray(disabledDates)]),
        disabled: false,
      },
    };
  }, [fromDate, toDate, disabledDates]);
};
