import { AttractionScheduleResponse } from "@parksandresorts/webapiproxy-types";
import { DateString } from "../helpers";
import ServiceHelper from "./service-helper";

export type AttractionScheduleParams = {
  /** The date for which to retrieve the schedule. If null/omitted, schedules for all available dates in the season are returned. */
  date?: DateString;
};

export const AttractionService = {
  getSchedule(optionalScheduleParams: AttractionScheduleParams = {}) {
    const queryString = new URLSearchParams(optionalScheduleParams as Record<string, string>).toString();
    return ServiceHelper.fetchGet<Array<AttractionScheduleResponse>>(
      `/openinghours/attractions/v1/schedule?${queryString}`,
    );
  },
};
