import styles from "./price-presentation-controls.module.less";
import { EntryVariant, VisitorCategory } from "@/core/types/services/purchase-flow-service-types";
import { PurchaseFlowDate } from "@/core/types/state/group-admission/group-admission-types";
import { LocationHelper, multipleClassNames } from "@/core/helpers";
import { useTranslation } from "react-i18next";
import SegmentedControls from "@/core/components/primitives/segmented-controls/segmented-controls";
import { TFunction } from "i18next";
import StyledRadioButtons from "@/core/components/primitives/styled-radio-buttons/styled-radio-buttons";
import StepBackdrop from "../../../components/step-backdrop";
import { LabelKey } from "@/core/labels/i18n";

export type PriceLevelData = {
  priceLevel: number;
  price: number;
  previousPrice?: number;
  productType?: ProductType;
  productVariant?: EntryVariant["id"];
  visitorCategory?: VisitorCategory["id"];
};

// The order in this array is important, as it is used to determine the order of the visitor categories in the calendar
export const ProductType = ["Jetpass", "Entry"] as const;

export type ProductType = (typeof ProductType)[number];

// When the price presenter is set to product type, the variant should always be "Day" and the visitor category "Adult"
export const PRODUCT_TYPE_PRICE_VARIANT_VALUE: EntryVariant["id"] = "Day";
export const PRODUCT_TYPE_PRICE_VISITOR_CATEGORY_VALUE: VisitorCategory["id"] = "Adult";

export const createCalendarFooterPricePresentation = (
  activePricePresentationValue: ProductType | VisitorCategory["id"],
  t: TFunction,
) => {
  const presentationValue =
    activePricePresentationValue === "Jetpass"
      ? t(`calendarStepPricingJetpassFooter`)
      : t(`calendarStepPricingOptions.${activePricePresentationValue}`);

  if (ProductType.includes(activePricePresentationValue as ProductType)) {
    return t(`calendarStepCalendarFooterInfoProductType`, { productType: presentationValue });
  }

  return t("calendarStepCalendarFooterInfoVisitorCategory", { visitorCategory: presentationValue });
};

export const createPricePresentationFromCalendarData = (
  selectedVisitorCategories: Array<VisitorCategory["id"]>,
  calendarData: Array<PurchaseFlowDate>,
): {
  uniqueProductTypes: Array<ProductType>;
  uniqueVisitorCategories: Array<VisitorCategory["id"]>;
} => {
  const hashInfo = LocationHelper.getDecodedHashParams();
  const productTicketTypeFromHash = hashInfo.ticket?.[0] as ProductType | undefined;

  const productTypesSet = new Set<ProductType>();
  const visitorCategoriesMap = new Map<VisitorCategory["id"], number>();

  for (const date of calendarData) {
    for (const product of date.products) {
      const productType: ProductType = product.productMetadata?.numberOfJetPassIncluded > 0 ? "Jetpass" : "Entry";
      productTypesSet.add(productType);

      const visitorCategory = product?.productMetadata?.visitorCategory;
      // We need to find the lowest sortIndex for each visitor category to determine the order of the visitor categories
      const dateCategory = date.visitorCategories.find((category) => category.id === visitorCategory);
      if (dateCategory && visitorCategory) {
        const currentMin = visitorCategoriesMap.get(visitorCategory) ?? Number.MAX_SAFE_INTEGER;
        visitorCategoriesMap.set(visitorCategory, Math.min(currentMin, dateCategory.sortIndex));
      }
    }
  }

  // We are doing a filter here to make sure the order is consistent. If the order is to be changed, update the ProductType array.
  const uniqueProductTypes = ProductType.filter((productType) => productTypesSet.has(productType));

  // If the product ticket type is present in the hash, we want to prioritize it in the sorting.
  // The rest of the product types should maintain their relative order.
  if (productTicketTypeFromHash) {
    uniqueProductTypes.sort((a, b) => {
      if (a === productTicketTypeFromHash) return -1;
      if (b === productTicketTypeFromHash) return 1;
      return 0;
    });
  }

  const uniqueVisitorCategories = [...visitorCategoriesMap.entries()]
    .sort(([, sortA], [, sortB]) => sortA - sortB)
    .map(([visitor]) => visitor)
    .filter((visitorCategory) => selectedVisitorCategories.includes(visitorCategory));

  return {
    uniqueProductTypes,
    uniqueVisitorCategories,
  };
};

type PricePresentationControlsProps = {
  toggleOptions: Array<ProductType> | Array<VisitorCategory["id"]>;
  visitorCategories: Map<VisitorCategory["id"], VisitorCategory>;
  activePricePresentationValue: ProductType | VisitorCategory["id"] | null;
  onPriceChange: (activeValue: ProductType | VisitorCategory["id"]) => void;
};

export const PricePresentationControls = ({
  toggleOptions,
  visitorCategories,
  activePricePresentationValue,
  onPriceChange,
}: PricePresentationControlsProps) => {
  const { t } = useTranslation();

  const segments = toggleOptions.map((option: ProductType | VisitorCategory["id"]) => ({
    label: t(`calendarStepPricingOptions.${option}`),
    contentfulLabelId: `calendarStepPricingOptions.${option}` satisfies LabelKey,
    // This sublabel mimicks the behavior in the GroupSize-component in the SegmentedControls.
    // Either for the visitor category or as a clarification for TTR in GLT.
    sublabel:
      t(`calendarStepPricingOptions.${option}Subheading` satisfies LabelKey<string | undefined>, "") ||
      visitorCategories.get(option as VisitorCategory["id"])?.description,
    value: option,
  }));

  if (segments.length < 2) {
    return null;
  }

  // We always want to use radio buttons if we are showing product types (e.g. TTR/Entrance on GLT)
  const useRadioButtos = segments.length > 2 || ProductType.includes(activePricePresentationValue as ProductType);

  return (
    <div className={styles.pricePresentationOuterWrapper}>
      <StepBackdrop>
        <div className={styles.pricePresentationInnerWrapper}>
          <p
            className={multipleClassNames("bold", styles.pricePresentationHeading)}
            data-contentful-label-id="calendarStepPricingHeading"
          >
            {t("calendarStepPricingHeading")}
          </p>
          {useRadioButtos ? (
            <StyledRadioButtons
              name="pricePresentation"
              value={activePricePresentationValue ?? segments[0].value}
              options={segments.map((segment) => ({
                ...segment,
                label: (
                  <div>
                    <b data-contentful-label-id={segment.contentfulLabelId}>{segment.label}</b>{" "}
                    {segment.sublabel && (
                      <span data-contentful-label-id={segment.contentfulLabelId + "Subheading"}>
                        ({segment.sublabel})
                      </span>
                    )}
                  </div>
                ),
              }))}
              displayMode="VERTICAL"
              onChange={(name, value) => onPriceChange(value as ProductType)}
            />
          ) : (
            <SegmentedControls
              dateKey="pricePresentation"
              name="pricePresentation"
              selectedValue={activePricePresentationValue ?? segments[0].value}
              segments={segments}
              onChange={onPriceChange}
            />
          )}
          <p
            className={multipleClassNames("p_tiny", styles.pricePresentationInformation)}
            data-contentful-label-id="calendarStepPricingInformation"
          >
            {t("calendarStepPricingInformation")}
          </p>
        </div>
      </StepBackdrop>
    </div>
  );
};
