import { useCallback, useEffect, useMemo, useState } from "react";
import { AnimatePresence } from "framer-motion";
import CalendarFooter from "@/core/components/primitives/calendar/calendar-footer/calendar-footer";
import Calendar from "@/core/components/primitives/calendar/calendar";
import { EventAggregator, TodayHelper } from "@/core/helpers";
import CalendarGroupings from "@/core/components/primitives/calendar-groupings/calendar-groupings";
import styles from "./daily-schedule.module.less";
import {
  addHashToUrlWithoutReload,
  createCalendarGrouping,
  createGroupingArray,
  findNextOpenDay,
  getDateFromHash,
} from "./functions/daily-schedule-functions";
import { ShowProps, Event } from "@/core/components/primitives/calendar/types/calendar-types";
import { LanguageHelper, DateHelper, isNonEmptyArray } from "@/core/helpers";
import { corei18n, defaultNamespace } from "@/core/labels/i18n";
import { useTranslation } from "react-i18next";
import { ExistingThemes } from "@/core/types/existing-themes";
import {
  useCalendarData,
  useDailyActivitiesContent,
  useEvents,
  useProductContent,
  usePromotionBanner,
  useRideAndRestaurantContent,
} from "./hooks/daily-schedule-hooks";
import { IContentfulLink } from "@/core/types/contentful-types";
import { RichTextType } from "@/core/components/primitives/rich-text/rich-text";
import { IGatsbyImageData } from "gatsby-plugin-image";
import structure from "@/core/styling/structure.module.less";
import { DailyScheduleSkeleton } from "@/core/components/primitives/calendar/daily-schedule-skeleton/daily-schedule-skeleton";
import { useDisabledDatesClickable } from "@/core/components/primitives/calendar/modifiers/useDisabledDatesClickable";
import { DateSet } from "@/core/helpers/date-helper";
import { LabelType } from "@/core/labels/label-type";
import { Tag } from "@/core/types/tag-type";

export type DateSpanProps = {
  firstDate: Date;
  lastDate: Date;
};

type GroupAdmissionList = {
  purchaseFlowId: number;
  connectedProduct: {
    contentful_id: string;
    id: string;
    componentTheme?: ExistingThemes;
    productName?: string;
    productImage?: {
      file: {
        url: string;
      };
      gatsbyImageData?: IGatsbyImageData;
    };
    productPageLink?: { slug: string };
    shortDescription?: string;
    customCtaText?: string;
  };
};

export type ScheduleList = {
  scheduleType: "Purchase Flows" | "Events" | "Restaurants" | "Attractions" | "Daily Activities";
  contentful_id: string;
  title: string;
  isExpanded?: boolean;
  listedByTags?: Array<Tag>;
  groupAdmissionList?: Array<GroupAdmissionList>;
};

export type DailyScheduleProps = {
  labelsOverride?: Partial<LabelType>;
  scheduleList?: Array<ScheduleList>;
  showConcertsInCalendar?: boolean;
  promotionBannerText?: RichTextType;
  promotionBannerLink?: IContentfulLink;
  concertInformationText?: RichTextType;
  concertInformationCTA?: IContentfulLink;
  dateInformationHeadline?: string;
  dateInformationText?: RichTextType;
  dateInformationDate?: Date;
  sortByTimeLabel?: string;
  sortByActivityLabel?: string;
};

type ExpandedGroupingState = {
  purchaseFlowGroup: Array<boolean>;
  eventScheduleGroup: Array<boolean>;
  restaurantGroups: Array<boolean>;
  attractionGroups: Array<boolean>;
  dailyActivityGroups: Array<boolean>;
};
const defaultExpandedGroupingState: ExpandedGroupingState = {
  purchaseFlowGroup: [true],
  eventScheduleGroup: [true],
  restaurantGroups: [],
  attractionGroups: [],
  dailyActivityGroups: [],
};

export type OpeningHoursResponseProps = {
  eventsByTime?: Array<Event>;
  eventsByActivity?: Array<ShowProps>;
};

const emptyPurchaseFlows: ScheduleList = {
  scheduleType: "Purchase Flows",
  contentful_id: "",
  title: "",
};

const DailySchedule = ({
  labelsOverride,
  scheduleList,
  showConcertsInCalendar,
  promotionBannerText,
  promotionBannerLink,
  concertInformationText,
  concertInformationCTA,
  dateInformationHeadline,
  dateInformationText,
  dateInformationDate,
}: DailyScheduleProps) => {
  const today = useMemo(() => TodayHelper.getNow(), []);
  const [selectedDate, setSelectedDate] = useState(() => getDateFromHash(TodayHelper.getNow()));
  const [events, isLoadingEvents] = useEvents();
  const [calendarData, isLoadingCalendarData] = useCalendarData(today);
  const [currentDisplayedMonth, setCurrentDisplayedMonth] = useState(() => getDateFromHash(TodayHelper.getNow()));
  const { purchaseFlows, eventSchedule, rideSchedules, restaurantSchedules, dailyActivitySchedules } = useMemo(() => {
    if (!isNonEmptyArray(scheduleList)) {
      return {};
    }
    const purchaseFlows = scheduleList.find((listItem) => listItem?.scheduleType === "Purchase Flows");
    const eventSchedule = scheduleList.find((listItem) => listItem?.scheduleType === "Events");
    const rideSchedules = scheduleList.filter((listItem) => listItem?.scheduleType === "Attractions");
    const restaurantSchedules = scheduleList.filter((listItem) => listItem?.scheduleType === "Restaurants");
    const dailyActivitySchedules = scheduleList.filter((listItem) => listItem?.scheduleType === "Daily Activities");
    return {
      purchaseFlows,
      eventSchedule,
      rideSchedules,
      restaurantSchedules,
      dailyActivitySchedules,
    };
  }, [scheduleList]);

  const [isExpandedGrouping, setIsExpandedGrouping] = useState<ExpandedGroupingState>({
    purchaseFlowGroup: [purchaseFlows?.isExpanded ?? defaultExpandedGroupingState.purchaseFlowGroup[0]],
    eventScheduleGroup: [eventSchedule?.isExpanded ?? defaultExpandedGroupingState.eventScheduleGroup[0]],
    restaurantGroups:
      restaurantSchedules?.map((schedule) => schedule?.isExpanded ?? false) ??
      defaultExpandedGroupingState.restaurantGroups,
    attractionGroups:
      rideSchedules?.map((schedule) => schedule?.isExpanded ?? false) ?? defaultExpandedGroupingState.attractionGroups,
    dailyActivityGroups:
      dailyActivitySchedules?.map((schedule) => schedule?.isExpanded ?? false) ??
      defaultExpandedGroupingState.dailyActivityGroups,
  });

  const purchaseFlowIds = useMemo(
    () => purchaseFlows?.groupAdmissionList?.map((flow) => flow.purchaseFlowId),
    [purchaseFlows],
  );

  const locale = LanguageHelper.currentLocale;
  const { t } = useTranslation();

  const openingHoursForSelectedDate =
    selectedDate && calendarData?.find((openDay) => DateHelper.isEqualYYYYMMDD(openDay.date, selectedDate));
  const isParkOpenToday = !!openingHoursForSelectedDate;
  const nextDateWithOpeningHours =
    selectedDate && !openingHoursForSelectedDate && findNextOpenDay(calendarData, selectedDate, today);

  const changeDate = (newDate: Date) => {
    setSelectedDate(newDate);
    const dateAsString = DateHelper.toStringYYYYMMDD(newDate);
    addHashToUrlWithoutReload(dateAsString);

    EventAggregator.publish("trackEvent", {
      category: "Daily Schedule Block",
      action: "Clicked date",
      label: `Selected dates: ${dateAsString}`,
    });
  };

  const toggleExpandedGrouping = useCallback((grouping: keyof ExpandedGroupingState, index = 0) => {
    setIsExpandedGrouping((previousState) => {
      const groupingIndex = previousState[grouping];
      const newGrouping = [...groupingIndex];
      newGrouping[index] = !newGrouping[index];
      return {
        ...previousState,
        [grouping]: newGrouping,
      };
    });
  }, []);

  useEffect(() => {
    corei18n.addResources(locale, defaultNamespace, labelsOverride);
  }, [locale, labelsOverride]);

  const [ridesAndRestaurantContent, isLoadingRideAndRestaurantContent] = useRideAndRestaurantContent(
    selectedDate,
    !!rideSchedules || !!restaurantSchedules,
  );
  const { rideContent, restaurantContent } = ridesAndRestaurantContent ?? {};

  const [dailyActivityContent, isLoadingActivities] = useDailyActivitiesContent(selectedDate, !!dailyActivitySchedules);

  const [productContent, isLoadingProductContent] = useProductContent(
    currentDisplayedMonth,
    purchaseFlowIds ?? [],
    purchaseFlows ?? emptyPurchaseFlows,
    locale,
  );

  const isLoadingCalendarGroupingData =
    isLoadingEvents ||
    isLoadingCalendarData ||
    isLoadingProductContent ||
    isLoadingActivities ||
    isLoadingRideAndRestaurantContent;

  const [promotionBannerShows] = usePromotionBanner(showConcertsInCalendar ?? false, today);

  const selectedDateGrouping = useMemo(() => {
    if (!selectedDate) {
      return [];
    }

    const selectedDateProducts = productContent?.get(DateHelper.toStringYYYYMMDD(selectedDate));

    const selectedDateGroupingProducts =
      isNonEmptyArray(selectedDateProducts) &&
      createCalendarGrouping(
        selectedDateProducts,
        purchaseFlows,
        selectedDate,
        isExpandedGrouping.purchaseFlowGroup[0],
        () => toggleExpandedGrouping("purchaseFlowGroup"),
        t("availableTickets"),
        "availableTickets",
      );

    const selectedDateEvents = events?.filter((event) =>
      DateHelper.isEqualYYYYMMDD(event.event.startDateAndTime, selectedDate),
    );

    const selectedDateGroupingEvents =
      isNonEmptyArray(selectedDateEvents) &&
      eventSchedule &&
      createCalendarGrouping(
        selectedDateEvents,
        eventSchedule,
        selectedDate,
        isExpandedGrouping.eventScheduleGroup[0],
        () => toggleExpandedGrouping("eventScheduleGroup"),
        t("todaysEvents"),
        "todaysEvents",
      );

    const selectedDateGroupingRides =
      isNonEmptyArray(rideContent) &&
      isNonEmptyArray(rideSchedules) &&
      rideSchedules.map((rideSchedule, index) => {
        return createCalendarGrouping(
          rideContent,
          rideSchedule,
          selectedDate,
          isExpandedGrouping.attractionGroups[index],
          () => toggleExpandedGrouping("attractionGroups", index),
          t("attractions"),
          "attractions",
          index,
        );
      });

    const selectedDateGroupingRestaurants =
      isNonEmptyArray(restaurantContent) &&
      isNonEmptyArray(restaurantSchedules) &&
      restaurantSchedules.map((restaurantSchedule, index) => {
        return createCalendarGrouping(
          restaurantContent,
          restaurantSchedule,
          selectedDate,
          isExpandedGrouping.restaurantGroups[index],
          () => toggleExpandedGrouping("restaurantGroups", index),
          t("restaurants"),
          "restaurants",
          index,
        );
      });

    const selectedDateGroupingDailyActivities =
      isNonEmptyArray(dailyActivityContent?.dailyActivities) &&
      isNonEmptyArray(dailyActivitySchedules) &&
      dailyActivitySchedules.map((dailyActivitySchedule, index) => {
        return createCalendarGrouping(
          [dailyActivityContent!],
          dailyActivitySchedule,
          selectedDate,
          isExpandedGrouping.dailyActivityGroups[index],
          () => toggleExpandedGrouping("dailyActivityGroups", index),
          t("dailyActivities"),
          "dailyActivities",
          index,
        );
      });

    const groupingArray = createGroupingArray(
      [
        selectedDateGroupingProducts,
        selectedDateGroupingEvents,
        ...(selectedDateGroupingRides || []),
        ...(selectedDateGroupingRestaurants || []),
        ...(selectedDateGroupingDailyActivities || []),
      ],
      [!purchaseFlows, !eventSchedule, !rideSchedules, !restaurantSchedules, !dailyActivitySchedules],
      scheduleList ?? [],
    );

    return groupingArray;
  }, [
    dailyActivityContent,
    dailyActivitySchedules,
    eventSchedule,
    events,
    isExpandedGrouping.attractionGroups,
    isExpandedGrouping.dailyActivityGroups,
    isExpandedGrouping.eventScheduleGroup,
    isExpandedGrouping.purchaseFlowGroup,
    isExpandedGrouping.restaurantGroups,
    productContent,
    purchaseFlows,
    restaurantContent,
    restaurantSchedules,
    rideContent,
    rideSchedules,
    scheduleList,
    selectedDate,
    t,
    toggleExpandedGrouping,
  ]);

  const days = new DateSet(calendarData?.map((d) => d.date));
  const { fromDate, toDate, modifiers } = useDisabledDatesClickable(
    today,
    calendarData?.at(-1)?.date ?? new Date(),
    (d) => !days.has(d),
  );

  return (
    <div className={styles.innerWrapper}>
      <div className={`${styles.calendarWrapper} ${structure.blockMaxWidthM}`}>
        <AnimatePresence mode="wait">
          {isLoadingCalendarData && <DailyScheduleSkeleton />}
          {!isLoadingCalendarData && (
            <>
              <Calendar
                selectedDate={selectedDate}
                changeDate={(newDate) => changeDate(newDate)}
                changedMonth={(newMonth: Date) => setCurrentDisplayedMonth(newMonth)}
                startDate={fromDate}
                endDate={toDate}
                modifiers={modifiers}
                currentDisplayedMonth={currentDisplayedMonth}
                animateEntry={true}
              />

              <CalendarFooter
                selectedDate={selectedDate}
                openingHours={openingHoursForSelectedDate}
                events={promotionBannerShows ?? undefined}
                promotionBannerText={promotionBannerText}
                promotionBannerLink={promotionBannerLink}
                nextOpenDay={nextDateWithOpeningHours ? nextDateWithOpeningHours.date : null}
                onChangeToNextOpenDate={(newDate: Date) => {
                  changeDate(newDate);
                  setCurrentDisplayedMonth(newDate);
                }}
                calendarOpeningTimes={t("calendarOpeningTimes")}
                contentfulLabelId="calendarOpeningTimes"
                concertInformationText={concertInformationText}
                concertInformationCTA={concertInformationCTA}
                dateInformationHeadline={dateInformationHeadline}
                dateInformationText={dateInformationText}
                dateInformationDate={dateInformationDate}
              />
            </>
          )}
        </AnimatePresence>
      </div>
      <CalendarGroupings
        groupings={selectedDateGrouping}
        showGroupings={isParkOpenToday}
        isLoading={isLoadingCalendarGroupingData}
      />
    </div>
  );
};

export default DailySchedule;
