import SessionStorageHelper from "./session-storage-helper";

const POST_MY_PARKS_LOGIN_KEY = "routeBeforeRedirect";
class LocationHelper {
  navigateBack() {
    if (typeof window !== "undefined") {
      window.history.go(-1);
    }
  }

  addHashToUrlWithoutReload(valuesArray: Array<{ key: string; value: string | Array<string> }>) {
    if (
      !(
        typeof document !== "undefined" &&
        typeof window !== "undefined" &&
        window.history &&
        window.history.replaceState
      )
    ) {
      return;
    }

    if (!(valuesArray instanceof Array && valuesArray.length > 0)) {
      return window.history.replaceState({}, `${document.title}`, window.location.pathname + window.location.search);
    }

    const delimiter = "&";
    const assignValue = "=";
    const valueStringsArray = valuesArray.map((item) => item.key + assignValue + item.value);
    const allValues = valueStringsArray.join(delimiter);

    window.history.replaceState({}, `${document.title}`, `#${allValues}`);
  }

  updateHistory(url: string, title: string, replace = false) {
    if (typeof window !== "undefined" && window.history && window.history.pushState && !replace) {
      window.history.pushState({ previousPath: window.location.pathname }, title, url);
    }

    if (typeof window !== "undefined" && window.history && window.history.replaceState && replace) {
      window.history.replaceState({}, title, url);
    }
  }

  getDecodedHashParams() {
    const hashParams: Record<string, Array<string>> = {};

    if (typeof window !== "undefined") {
      if (window.location && window.location.hash) {
        window.location.hash
          .substring(1)
          .split("&")
          .forEach((item) => {
            let [k, v] = item.split(`=`);
            v = v && decodeURIComponent(v);
            (hashParams[k] = hashParams[k] || []).push(v);
          });
      }
    }
    return hashParams;
  }

  getQueryParams() {
    const pageParams: Record<string, Array<string>> = {};

    if (typeof window !== "undefined") {
      if (window.location.search) {
        window.location.search
          .substring(1)
          .split(`&`)
          .forEach((item) => {
            let [k, v] = item.split(`=`);
            v = v && decodeURIComponent(v);
            (pageParams[k] = pageParams[k] || []).push(v);
          });
      }
    }
    return pageParams;
  }

  /** Removes a query param from the current URL, keeping other params + hash. No-op if absent or during SSR. */
  removeQueryParam(key: string) {
    if (typeof window === "undefined" || !window.history || !window.history.replaceState) {
      return;
    }

    const url = new URL(window.location.href);
    if (!url.searchParams.has(key)) {
      return;
    }

    url.searchParams.delete(key);
    const search = url.searchParams.toString();
    const newUrl = `${url.pathname}${search ? `?${search}` : ""}${url.hash}`;
    window.history.replaceState({}, document.title, newUrl);
  }

  getChannelFromQuery() {
    const pageParams = this.getQueryParams();

    return pageParams instanceof Object &&
      pageParams.channel instanceof Array &&
      pageParams.channel.length &&
      pageParams.channel[0]
      ? pageParams.channel[0]
      : "";
  }

  setPostMyParksLogin(postLoginUrl: string, pageName?: string) {
    const routeBeforeRedirect = {
      pageName: pageName,
      pageUrl: postLoginUrl,
    };

    SessionStorageHelper.setItem(POST_MY_PARKS_LOGIN_KEY, routeBeforeRedirect, null);
  }

  getPostMyParksLogin() {
    const routeBeforeRedirect:
      | {
          pageName: string;
          pageUrl?: string;
        }
      | undefined
      | null = SessionStorageHelper.getItem(POST_MY_PARKS_LOGIN_KEY);

    if (routeBeforeRedirect && routeBeforeRedirect.pageUrl) {
      return routeBeforeRedirect;
    }

    return null;
  }

  clearPostMyParksLogin() {
    SessionStorageHelper.removeItem(POST_MY_PARKS_LOGIN_KEY);
  }
}

const singleton = new LocationHelper();
export default singleton;
