const getEventsForSelectedDate = (events: Array<ContentfulEvent>, selectedDate: Date): Array<ContentfulEvent> => {
  return events.filter((event) => DateHelper.isEqualYYYYMMDD(event.startDateAndTime, selectedDate));
};

type ScheduleForSelectedDate = {
  event: ContentfulEvent;
  externalEntry?: ContentfulExternalEntry;
  internalTitle: string;
};

const getRideContentFromScheduleQueueTimes = (
  allAttractionsSchedules: Array<AttractionScheduleResponse>,
  allQueueTimes: Array<QueueTimeItem>,
  selectedDate: Date,
): Array<RideContent> => {
  const selectedDateString = DateHelper.toStringYYYYMMDD(selectedDate);
  const rideContentArray: Array<RideContent> = [];

  for (const schedule of allAttractionsSchedules) {
    const isToday = schedule.today?.date === selectedDateString;
    const { scheduleForDate, queueTime } = isToday
      ? {
          scheduleForDate: schedule.today,
          queueTime: allQueueTimes.find((qt) => schedule.attractionId === qt.attractionId),
        }
      : {
          scheduleForDate: schedule.seasonSchedule?.find((s) => s.date === selectedDateString),
          queueTime: undefined,
        };

    if (!scheduleForDate || !isNonEmptyArray(scheduleForDate.operatingTimes)) continue;

    const foundRide = RideStore.getRideById(schedule.attractionId);
    if (foundRide) {
      const { queueState, stoppageStatus } = getRideQueueData(queueTime);
      rideContentArray.push({
        ...foundRide,
        scheduleForDate,
        queueState,
        stoppage: stoppageStatus,
        type: "ride",
        contentSource: "schedule",
      });
    }
  }

  return rideContentArray.sort((a, b) => (a.sortIndex ?? 0) - (b.sortIndex ?? 0));
};

const getRideAndRestaurantContent = async (
  selectedDate: Date,
): Promise<{ rideContent: Array<RideContent>; restaurantContent: Array<RestaurantContent> }> => {
  const getRideContentItem = (schedule: ScheduleForSelectedDate): RideContentContentful | null => {
    const foundRide =
      schedule.externalEntry?.externalEntryId &&
      RideStore.getRideByContentfulId(schedule.externalEntry.externalEntryId);
    return foundRide ? { ...foundRide, ...schedule, type: "ride", contentSource: "contentful" } : null;
  };

  const getRestaurantContentItem = (schedule: ScheduleForSelectedDate): RestaurantContent | null => {
    const foundRestaurant =
      schedule.externalEntry?.externalEntryId &&
      RestaurantStore.getRestaurantsByContentfulId(schedule.externalEntry.externalEntryId);
    return foundRestaurant ? { ...foundRestaurant, ...schedule, type: "restaurant" } : null;
  };

  try {
    const response = await ScheduleStore.getSchedulesForTypes(["OpeningHour"]);
    const rideContentArray: Array<RideContentContentful> = [];
    const restaurantContentArray: Array<RestaurantContent> = [];

    for (const schedule of response) {
      const eventForSelectedDate = getEventsForSelectedDate(schedule.events ?? [], selectedDate);

      if (isNonEmptyArray(eventForSelectedDate)) {
        const { internalTitle, externalEntry } = schedule;
        const scheduleForSelectedDate = { internalTitle, externalEntry, event: eventForSelectedDate[0] };

        const rideContent = getRideContentItem(scheduleForSelectedDate);
        const restaurantContent = getRestaurantContentItem(scheduleForSelectedDate);

        rideContent && rideContentArray.push(rideContent);
        restaurantContent && restaurantContentArray.push(restaurantContent);
      }
    }

    rideContentArray.sort((a, b) => (a.sortIndex ?? 0) - (b.sortIndex ?? 0));
    restaurantContentArray.sort((a, b) => (a.sortIndex ?? 0) - (b.sortIndex ?? 0));
    return { rideContent: rideContentArray, restaurantContent: restaurantContentArray };
  } catch (err) {
    EventAggregator.publish("trackException", {
      exception: err,
      customMessage: "DailySchedule getRideAndRestaurantContent",
    });
    throw err;
  }
};

const getRestaurantContent = async (selectedDate: Date): Promise<Array<RestaurantContent>> => {
  const getRestaurantContentItem = (schedule: ScheduleForSelectedDate): RestaurantContent | null => {
    const foundRestaurant =
      schedule.externalEntry?.externalEntryId &&
      RestaurantStore.getRestaurantsByContentfulId(schedule.externalEntry.externalEntryId);
    return foundRestaurant ? { ...foundRestaurant, ...schedule, type: "restaurant" } : null;
  };

  try {
    const response = await ScheduleStore.getSchedulesForTypes(["OpeningHour"]);
    const restaurantContentArray: Array<RestaurantContent> = [];

    for (const schedule of response) {
      const eventForSelectedDate = getEventsForSelectedDate(schedule.events ?? [], selectedDate);

      if (isNonEmptyArray(eventForSelectedDate)) {
        const { internalTitle, externalEntry } = schedule;
        const scheduleForSelectedDate = { internalTitle, externalEntry, event: eventForSelectedDate[0] };
        const restaurantContent = getRestaurantContentItem(scheduleForSelectedDate);
        restaurantContent && restaurantContentArray.push(restaurantContent);
      }
    }

    return restaurantContentArray.sort((a, b) => (a.sortIndex ?? 0) - (b.sortIndex ?? 0));
  } catch (err) {
    EventAggregator.publish("trackException", {
      exception: err,
      customMessage: "DailySchedule getRestaurantContent",
    });
    throw err;
  }
};

const getDailyActivitiesContent = async (selectedDate: Date) => {
  try {
    const response = await ScheduleStore.getSchedulesForTypes(["DailyActivity"]);
    const dailyActivities: Array<ShowNode & ContentfulSchedule> = [];
    response.forEach((schedule) => {
      const eventsForSelectedDate = getEventsForSelectedDate(schedule.events ?? [], selectedDate).sort((a, b) =>
        DateHelper.compareDates(a.startDateAndTime, b.startDateAndTime),
      );

      if (isNonEmptyArray(eventsForSelectedDate)) {
        const foundActivity =
          schedule.externalEntry?.externalEntryId && ShowStore.getShowByShowId(schedule.externalEntry.externalEntryId);
        foundActivity &&
          dailyActivities.push({
            ...schedule,
            ...foundActivity,
            internalTitle: schedule.internalTitle,
            events: eventsForSelectedDate,
          });
      }
    });

    return { dailyActivities: dailyActivities, type: "dailyActivity" } as DailyActivityContent;
  } catch (err) {
    EventAggregator.publish("trackException", {
      exception: err,
      customMessage: "DailySchedule getDailyActivitiesContent",
    });
    throw err;
  }
};

const getProductContent = async (
  purchaseFlowIds: Array<number>,
  purchaseFlows: ScheduleList,
  datesOfCurrentMonth: DateSpanProps,
  locale: string,
) => {
  try {
    const response = await PurchaseFlowService.getPurchaseFlows(
      purchaseFlowIds,
      DateHelper.toStringYYYYMMDD(datesOfCurrentMonth.firstDate),
      DateHelper.toStringYYYYMMDD(datesOfCurrentMonth.lastDate),
      locale,
    );
    const contentCopy = new Map<string, Array<ProductContent>>();
    const newProductContent = response && transformPurchaseFlowsToProductContent(response, purchaseFlows);
    newProductContent.forEach((content, key) => {
      contentCopy.set(key, content);
    });
    const sortedNewContent = new Map([...contentCopy.entries()].sort());
    return sortedNewContent;
  } catch (err) {
    EventAggregator.publish("trackException", {
      exception: err,
      customMessage: "DailySchedule getProductContent",
    });
    throw err;
  }
};

const createGroupingArray = (
  selectedDateGroupings: Array<CalendarGrouping | undefined | false>,
  hideGroups: Array<boolean>,
  scheduleList: Array<ScheduleList>,
) => {
  const scheduleListOrder = scheduleList.map((item) => item.contentful_id);

  return zip(selectedDateGroupings, hideGroups)
    .filter(([grouping, hide]) => grouping && !hide)
    .map(([grouping]) => grouping as CalendarGrouping)
    .sort((a, b) => {
      const indexA = scheduleListOrder.indexOf(a.scheduleListId);
      const indexB = scheduleListOrder.indexOf(b.scheduleListId);
      return indexA - indexB;
    });
};

const createCalendarGrouping = (
  grouping: Array<CalendarGroupingContent>,
  listProps: ScheduleList | undefined,
  selectedDate: Date,
  isExpanded: boolean,
  onClick: () => void,
  fallbackTitle: string,
  contentfulLabelId: string,
  index?: number,
) => {
  let filteredGroupingContent = grouping;

  const tagList = listProps?.listedByTags;
  if (isNonEmptyArray(tagList)) {
    // Check if a group has any matching tags with the schedule list
    const hasMatchingTags = (content: RideContent | RestaurantContent | (ShowNode & ContentfulSchedule)) =>
      content.tags?.some((tag) => tagList.some((listTag) => listTag.title === tag.title));

    filteredGroupingContent = grouping
      .map((group) => {
        if (group?.type === "restaurant" || group?.type === "ride") {
          return hasMatchingTags(group) && group;
        }
        if (group?.type === "dailyActivity") {
          const filteredActivities = group.dailyActivities.filter((activity) => hasMatchingTags(activity));

          return { ...group, dailyActivities: filteredActivities };
        }
        return null;
      })
      .filter(isTruthy);
  }

  if (!isNonEmptyArray(filteredGroupingContent)) {
    return undefined;
  }

  return {
    heading: insertIntoString(listProps?.title ?? fallbackTitle, DateHelper.toStringDDMonth(selectedDate)),
    key: `${fallbackTitle}-${selectedDate}-${index}`,
    content: filteredGroupingContent,
    selectedDate: DateHelper.toStringYYYYMMDD(selectedDate),
    isExpanded: isExpanded,
    onClick: onClick,
    contentfulLabelId: contentfulLabelId,
    scheduleListId: listProps?.contentful_id ?? "",
  };
};

const transformParkOpeningHoursToCalendarData = (openingHoursResponse: Array<OpeningHoursItem>) => {
  if (!isNonEmptyArray(openingHoursResponse)) {
    return [];
  }
  const calendarData: Array<CalendarDataProps> = openingHoursResponse.map((openingHours) => {
    const dateFrom = createDate(openingHours.opens);
    const dateTo = createDate(openingHours.closing);

    const calendarItem = {
      date: dateFrom,
      openingTime: DateHelper.toStringTimeHHMM(dateFrom),
      closingTime: DateHelper.toStringTimeHHMM(dateTo),
      passes: openingHours.passes ?? [],
    };

    return calendarItem;
  });
  return calendarData;
};

const sectionCalendarProducts = (
  productsArray: Array<Product>,
  purchaseFlow: PurchaseFlowResponse,
): Array<ProductPriceGroupGroups> => {
  const filteredAndSortedProducts = productsArray
    .filter((product) => product.dateSlot)
    .sort((a, b) => b.price - a.price);

  const sectionedCalendarProducts: Array<ProductPriceGroupGroups> = filteredAndSortedProducts
    .map((product) => {
      const entryVariant = purchaseFlow.entryVariants[product.productMetadata.entryVariant!];
      const visitorCategory = purchaseFlow.visitorCategories[product.productMetadata.visitorCategory!];

      return {
        groupName: entryVariant.name,
        prices: [
          {
            category: visitorCategory.name,
            price: CurrencyHelper.formatToSek(product.price),
            isSoldOut: product.dateSlot.quantity === 0,
            visitorCategory: visitorCategory,
          },
        ],
        entryVariant: entryVariant,
      } satisfies ProductPriceGroupGroups;
    })
    .sort((a, b) => {
      // sort by entryVariant
      return sortIndexComparer(a.entryVariant, b.entryVariant);
    });

  return sectionedCalendarProducts;
};

const groupProductsByEntryVariant = (
  sectionedCalendarProducts: Array<ProductPriceGroupGroups>,
  calendarDate: string,
) => {
  const groupedProductsByEntryVariant = sectionedCalendarProducts.reduce(
    (acc, product) => {
      if (!acc[product.groupName]) {
        acc[product.groupName] = [];
      }
      acc[product.groupName].push(product);
      return acc;
    },
    {} as Record<string, Array<ProductPriceGroupGroups>>,
  );

  const groupedWithAllPrices = Object.values(groupedProductsByEntryVariant).map((productGroup) => {
    const prices = productGroup
      .map(({ prices }) => prices)
      .filter((prices): prices is Exclude<typeof prices, "soldOut"> => prices !== "soldOut")
      .flat()
      .sort((a, b) => sortIndexComparer(a.visitorCategory, b.visitorCategory));

    return {
      ...productGroup[0],
      prices: prices.length > 0 ? prices : ("soldOut" as const),
    };
  });

  return { [calendarDate]: groupedWithAllPrices };
};

const transformPurchaseFlowsToProductContent = (
  purchaseFlowsFromApi: Array<PurchaseFlowResponse>,
  purchaseFlowsFromContentful: ScheduleList,
) => {
  const productContentMap = new Map<string, Array<ProductContent>>();

  purchaseFlowsFromApi.map((purchaseFlow) => {
    const contentfulPurchaseFlowData = purchaseFlowsFromContentful.groupAdmissionList?.find(
      (groupAdmission) => groupAdmission.purchaseFlowId === purchaseFlow.purchaseFlowId,
    );
    const productProps = contentfulPurchaseFlowData?.connectedProduct;
    const heading = purchaseFlow.purchaseFlowName;
    const productImageUrl = productProps?.productImage?.file?.url;
    const productShortDescription = productProps?.shortDescription;
    const productPageLink = productProps?.productPageLink?.slug;
    const productComponentTheme = productProps?.componentTheme;
    const productButtonLabel = productProps?.customCtaText ?? corei18n.t("bookNow");
    const productTicketType: ProductType = purchaseFlow.selectJetPass ? "Jetpass" : "Entry";
    const productGroups = purchaseFlow.calendar
      .filter((calendar) => isNonEmptyArray(calendar.products))
      .map((day) => {
        const calendarDate = DateHelper.toStringYYYYMMDD(day.date);

        // get relevant data for each product
        const sectionedCalendarProducts = sectionCalendarProducts(day.products, purchaseFlow);

        // group new product structure based on entry variant
        const groupedProductsByEntryVariant = groupProductsByEntryVariant(sectionedCalendarProducts, calendarDate);

        const productContent: ProductContent = {
          type: "product",
          ticketType: productTicketType,
          dateKey: calendarDate,
          heading: heading,
          paragraph: productShortDescription || "",
          buttonLabel: productButtonLabel,
          imageUrl: productImageUrl,
          image: productProps?.productImage?.gatsbyImageData,
          buttonAction: productPageLink,
          componentTheme: productComponentTheme,
        };

        return {
          productContent: productContent,
          groupedProducts: groupedProductsByEntryVariant,
        };
      });

    const filteredProductGroupsByValues = productGroups.filter(({ groupedProducts }) => {
      const productsValues = Object.values(groupedProducts).flat();
      if (productsValues.length === 0) {
        return false;
      }
      return true;
    });

    const mappedProductGroups = filteredProductGroupsByValues.map(({ productContent, groupedProducts }) => {
      const dateKey = Object.keys(groupedProducts)[0];
      const groupValues = Object.values(groupedProducts).flat();
      const productGroupIsSoldOut = groupValues.every((value) => {
        return value.prices === "soldOut" || value.prices.every((price) => price.isSoldOut);
      });

      if (productGroupIsSoldOut) {
        return {
          date: dateKey,
          content: {
            ...productContent,
            buttonLabel: corei18n.t("soldOutToday").toUpperCase(),
            isDisabled: true,
          },
        };
      }

      // if all prices are sold out, remove prices from group
      const groupsWithoutPricesForSoldOutGroups = groupValues.map((group) => {
        if (group.prices === "soldOut" || group.prices.every((price) => price.isSoldOut)) {
          return {
            ...group,
            prices: "soldOut" as const,
          };
        }
        return group;
      });

      if (groupsWithoutPricesForSoldOutGroups.length === 1) {
        return {
          date: dateKey,
          content: {
            ...productContent,
            productsPricesHeading: groupsWithoutPricesForSoldOutGroups[0].groupName,
            productsPrices: { type: "list", prices: groupsWithoutPricesForSoldOutGroups[0].prices },
          } satisfies ProductContent,
        };
      }

      return {
        date: dateKey,
        content: {
          ...productContent,
          productsPrices: { type: "groups", groups: groupsWithoutPricesForSoldOutGroups },
        } satisfies ProductContent,
      };
    });

    mappedProductGroups.forEach((group) => {
      const productInMap = productContentMap.get(group.date);

      if (!productInMap) {
        productContentMap.set(group.date, [group.content]);
        return;
      }

      productContentMap.set(group.date, [...productInMap, group.content]);
    });
  });
  return productContentMap;
};

const getDateSpan = (currentDisplayedMonth: Date) => {
  const firstDate = dayjs(currentDisplayedMonth).startOf("month").toDate();
  const lastDate = dayjs(currentDisplayedMonth).endOf("month").toDate();
  const newDateSpan: DateSpanProps = { firstDate, lastDate };
  return newDateSpan;
};

/**
 * Find the next open day that is later than the selected date and equal or later than today.
 */
const findNextOpenDay = (calendarData: Array<CalendarDataProps> | undefined, selectedDate: Date, today: Date) => {
  if (!(calendarData instanceof Array && calendarData.length > 0) || !DateHelper.isDateValid(selectedDate)) {
    return null;
  }

  return calendarData.find(
    (openDay) =>
      openDay.date > selectedDate && (DateHelper.isEqualYYYYMMDD(openDay.date, today) || openDay.date > today),
  );
};

const extendEvents = (events: Array<Event>): EventContent[] => {
  return events.map((event) => {
    const show = ShowStore.getShowByShowId(event.showId);

    return {
      event,
      show: show ?? undefined,
      onClick: show?.pageLink?.slug ?? undefined,
      type: "event",
    } satisfies EventContent;
  });
};

const getDateFromHash = (today: Date) => {
  const { date } = LocationHelper.getDecodedHashParams();
  const dateFromHash = date?.[0];
  const dateObjectFromHash = dateFromHash && createDate(dateFromHash);
  const validatedDate =
    DateHelper.isDateValid(dateObjectFromHash) && !DateHelper.hasDatePassed(dateObjectFromHash)
      ? dateObjectFromHash || today
      : today;
  return validatedDate;
};

const addHashToUrlWithoutReload = (dateString: string) => {
  const locationParams = [{ key: "date", value: dateString }];
  LocationHelper.addHashToUrlWithoutReload(locationParams);
};

