const getOpeningHours = (startDate: string, endDate: string): OpeningHoursItem[] => {
  const start = new Date(startDate);
  const end = new Date(endDate);
  const oneDay = 24 * 60 * 60 * 1000; // milliseconds in a day

  const newOpeningHoursResponse = [];

  // iterate over each day in the date range
  for (let d = start; d <= end; d.setTime(d.getTime() + oneDay)) {
    const openingTime = dayjs(d).set("hour", 10).toString();
    const closingTime = dayjs(d).set("hour", 22).toString();
    const openingHours: OpeningHoursItem = {
      opens: openingTime,
      closing: closingTime,
      ...constantOpeningHoursParts,
      areaOpeningHours: [
        {
          areaId: 1,
          dateFrom: d.toISOString(),
          dateTo: d.toISOString(),
        },
      ],
    };
    newOpeningHoursResponse.push(openingHours);
  }

  return newOpeningHoursResponse;
};

const openingHoursResponse = getOpeningHours(firstDate, lastDate);

