const getCalendarDates = () => {
  const newCalendarDates = [];

  for (let i = 0; i <= 30; i++) {
    newCalendarDates.push({
      date: DateHelper.toStringTimeYYYYMMDDHHMM(today.add(i, "day").set("hour", 0).set("minute", 0)),
      opens: DateHelper.toStringTimeYYYYMMDDHHMM(today.add(i, "day").set("hour", 15).set("minute", 0)),
      closing: DateHelper.toStringTimeYYYYMMDDHHMM(today.add(i, "day").set("hour", 21).set("minute", 0)),
      products: constantProduct,
    });
  }

  return newCalendarDates;
};

