import { useQuery } from "@tanstack/react-query";
import { AttractionScheduleParams, AttractionService } from "../services/attraction-service";
import { useOrderedKeys } from "./use-ordered-keys";

export function useAttractionsSchedule(options: AttractionScheduleParams, enabled = true) {
  const queryParams = useOrderedKeys(options, ["date"]);

  return useQuery({
    queryKey: ["attractions.schedule", queryParams],
    queryFn: () => AttractionService.getSchedule(queryParams),
    staleTime: Infinity, // Schedules rarely update, and this is an expensive request
    enabled,
  });
}
